// Formula parsing and evaluation.
import { parseAddr, toAddr } from "./addr.mjs";

const REF = /^\$?[A-Za-z]{1,3}\$?[1-9]\d*(?![A-Za-z0-9_.(])/;
const NUM = /^(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/;
const IDENT = /^[A-Za-z_][A-Za-z0-9_.]*/;
const OPS = ["<>", "<=", ">=", "=", "<", ">", "&", "+", "-", "*", "/", "^", "(", ")", ",", ":"];

function tokenize(text) {
  const toks = [];
  let i = 0;
  while (i < text.length) {
    const rest = text.slice(i);
    let m;
    if (/^\s/.test(rest)) { i++; continue; }
    if (rest[0] === '"') {
      let j = i + 1, s = "";
      for (;;) {
        if (j >= text.length) throw new SyntaxError("unterminated string");
        if (text[j] === '"') {
          if (text[j + 1] === '"') { s += '"'; j += 2; continue; }
          break;
        }
        s += text[j++];
      }
      toks.push({ k: "str", v: s });
      i = j + 1;
    } else if ((m = NUM.exec(rest)) && !/^[A-Za-z_$]/.test(rest.slice(m[0].length))) {
      toks.push({ k: "num", v: Number(m[0]) });
      i += m[0].length;
    } else if ((m = REF.exec(rest))) {
      toks.push({ k: "ref", v: m[0] });
      i += m[0].length;
    } else if ((m = IDENT.exec(rest))) {
      toks.push({ k: "id", v: m[0] });
      i += m[0].length;
    } else {
      const op = OPS.find((o) => rest.startsWith(o));
      if (!op) throw new SyntaxError(`unexpected character '${rest[0]}'`);
      toks.push({ k: "op", v: op });
      i += op.length;
    }
  }
  return toks;
}

const normRef = (t) => { const a = parseAddr(t); return toAddr(a.col, a.row); };

export function parseFormula(text) {
  const toks = tokenize(String(text));
  let p = 0;
  const peek = () => toks[p];
  const isOp = (v) => toks[p] && toks[p].k === "op" && toks[p].v === v;
  const expect = (v) => { if (!isOp(v)) throw new SyntaxError(`expected '${v}'`); p++; };

  const level = (ops, next) => () => {
    let l = next();
    while (peek() && peek().k === "op" && ops.includes(peek().v)) {
      const op = toks[p++].v;
      l = { t: "bin", op, l, r: next() };
    }
    return l;
  };
  const unary = () => {
    if (isOp("-") || isOp("+")) { const op = toks[p++].v; return { t: "un", op, x: unary() }; }
    return primary();
  };
  const pow = level(["^"], unary);
  const mul = level(["*", "/"], pow);
  const add = level(["+", "-"], mul);
  const cat = level(["&"], add);
  const cmp = level(["=", "<>", "<", ">", "<=", ">="], cat);

  function primary() {
    const t = toks[p++];
    if (!t) throw new SyntaxError("unexpected end of formula");
    if (t.k === "num") return { t: "num", v: t.v };
    if (t.k === "str") return { t: "str", v: t.v };
    if (t.k === "ref") {
      const a = normRef(t.v);
      if (isOp(":")) {
        p++;
        const n = toks[p++];
        if (!n || n.k !== "ref") throw new SyntaxError("bad range");
        const b = normRef(n.v);
        const x = parseAddr(a), y = parseAddr(b);
        return { t: "range", c1: Math.min(x.col, y.col), c2: Math.max(x.col, y.col), r1: Math.min(x.row, y.row), r2: Math.max(x.row, y.row) };
      }
      return { t: "ref", addr: a };
    }
    if (t.k === "id") {
      if (isOp("(")) {
        p++;
        const args = [];
        if (!isOp(")")) {
          for (;;) {
            args.push(cmp());
            if (isOp(",")) { p++; continue; }
            break;
          }
        }
        expect(")");
        return { t: "call", name: t.v.toUpperCase(), args };
      }
      const u = t.v.toUpperCase();
      if (u === "TRUE" || u === "FALSE") return { t: "bool", v: u === "TRUE" };
      return { t: "name", name: u };
    }
    if (t.v === "(") { const e = cmp(); expect(")"); return e; }
    throw new SyntaxError(`unexpected '${t.v}'`);
  }

  const ast = cmp();
  if (p < toks.length) throw new SyntaxError(`unexpected '${toks[p].v}'`);
  return ast;
}

function rangeAddrs(n) {
  const out = [];
  for (let r = n.r1; r <= n.r2; r++) for (let c = n.c1; c <= n.c2; c++) out.push(toAddr(c, r));
  return out;
}

export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    if (n.t === "ref") seen.add(n.addr);
    else if (n.t === "range") rangeAddrs(n).forEach((a) => seen.add(a));
    else if (n.t === "un") walk(n.x);
    else if (n.t === "bin") { walk(n.l); walk(n.r); }
    else if (n.t === "call") n.args.forEach(walk);
  };
  walk(ast);
  return [...seen];
}

const isErr = (v) => typeof v === "string" && v.startsWith("#");
const NUMSTR = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/;

function toNum(v) {
  if (isErr(v)) return v;
  if (v === null) return 0;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "number") return v;
  const t = v.trim();
  return t !== "" && NUMSTR.test(t) ? Number(t) : "#VALUE!";
}
const toText = (v) => (v === null ? "" : typeof v === "boolean" ? (v ? "TRUE" : "FALSE") : String(v));
function toBool(v) {
  if (isErr(v)) return v;
  if (v === null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const u = v.toUpperCase();
  return u === "TRUE" ? true : u === "FALSE" ? false : "#VALUE!";
}
const fin = (x) => (Number.isFinite(x) ? x : "#NUM!");

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);
function compare(a, b) {
  if (a === null && b === null) { a = 0; b = 0; }
  else if (a === null) a = typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  else if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  if (rank(a) !== rank(b)) return rank(a) - rank(b);
  if (typeof a === "string") { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

const shift = (x, n) => { const [m, e] = x.toExponential().split("e"); return Number(`${m}e${Number(e) + n}`); };
function round(x, d) {
  d = Math.trunc(d);
  const a = Math.abs(x);
  if (a >= 1e21 || a === 0) return x;
  const r = shift(Math.round(shift(a, d)), -d);
  return (x < 0 ? -r : r) || 0;
}

export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.t) {
      case "num": case "str": case "bool": return n.v;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "name": return "#NAME?";
      case "un": {
        const x = toNum(ev(n.x));
        if (typeof x === "string") return x;
        return n.op === "-" ? fin(-x) || 0 : x;
      }
      case "bin": return binary(n);
      case "call": return call(n);
    }
  };

  function binary(n) {
    const l = ev(n.l), r = ev(n.r);
    if (isErr(l)) return l;
    if (isErr(r)) return r;
    switch (n.op) {
      case "&": return toText(l) + toText(r);
      case "=": return compare(l, r) === 0;
      case "<>": return compare(l, r) !== 0;
      case "<": return compare(l, r) < 0;
      case ">": return compare(l, r) > 0;
      case "<=": return compare(l, r) <= 0;
      case ">=": return compare(l, r) >= 0;
    }
    const a = toNum(l), b = toNum(r);
    if (typeof a === "string") return a;
    if (typeof b === "string") return b;
    switch (n.op) {
      case "+": return fin(a + b);
      case "-": return fin(a - b);
      case "*": return fin(a * b);
      case "/": return b === 0 ? "#DIV/0!" : fin(a / b);
      case "^": return fin(a ** b);
    }
  }

  // Values of an argument: [list, isRange]
  const rangeVals = (n) => rangeAddrs(n).map(lookup);

  function call(n) {
    const { name, args } = n;
    const argc = args.length;
    const bad = "#VALUE!";
    const noRange = () => args.some((a) => a.t === "range");
    switch (name) {
      case "SUM": case "AVERAGE": case "MIN": case "MAX": case "COUNT": {
        const nums = [];
        let count = 0;
        for (const a of args) {
          if (a.t === "range") {
            for (const v of rangeVals(a)) {
              if (typeof v === "number") nums.push(v);
              else if (name !== "COUNT" && isErr(v)) return v;
            }
          } else {
            const v = ev(a);
            if (name === "COUNT") { if (typeof v === "number") nums.push(v); continue; }
            const x = toNum(v);
            if (typeof x === "string") return x;
            nums.push(x);
          }
        }
        count = nums.length;
        switch (name) {
          case "COUNT": return count;
          case "SUM": return fin(nums.reduce((s, x) => s + x, 0));
          case "AVERAGE": return count ? fin(nums.reduce((s, x) => s + x, 0) / count) : "#DIV/0!";
          case "MIN": return count ? Math.min(...nums) : 0;
          case "MAX": return count ? Math.max(...nums) : 0;
        }
        return bad;
      }
      case "IF": {
        if (argc < 2 || argc > 3 || noRange()) return bad;
        const c = toBool(ev(args[0]));
        if (typeof c === "string") return c;
        return c ? ev(args[1]) : argc === 3 ? ev(args[2]) : false;
      }
      case "AND": case "OR": {
        if (argc < 1) return bad;
        const bools = [];
        for (const a of args) {
          if (a.t === "range") {
            for (const v of rangeVals(a)) {
              if (isErr(v)) return v;
              if (typeof v === "number") bools.push(v !== 0);
              else if (typeof v === "boolean") bools.push(v);
            }
          } else {
            const b = toBool(ev(a));
            if (typeof b === "string") return b;
            bools.push(b);
          }
        }
        return name === "AND" ? bools.every(Boolean) : bools.some(Boolean);
      }
      case "NOT": {
        if (argc !== 1 || noRange()) return bad;
        const b = toBool(ev(args[0]));
        return typeof b === "string" ? b : !b;
      }
      case "ROUND": {
        if (argc !== 2 || noRange()) return bad;
        const x = toNum(ev(args[0]));
        if (typeof x === "string") return x;
        const d = toNum(ev(args[1]));
        if (typeof d === "string") return d;
        return fin(round(x, d));
      }
      case "ABS": {
        if (argc !== 1 || noRange()) return bad;
        const x = toNum(ev(args[0]));
        return typeof x === "string" ? x : Math.abs(x);
      }
      case "LEN": case "UPPER": case "LOWER": {
        if (argc !== 1 || noRange()) return bad;
        const v = ev(args[0]);
        if (isErr(v)) return v;
        const s = toText(v);
        return name === "LEN" ? s.length : name === "UPPER" ? s.toUpperCase() : s.toLowerCase();
      }
      case "CONCAT": {
        let out = "";
        for (const a of args) {
          const vs = a.t === "range" ? rangeVals(a) : [ev(a)];
          for (const v of vs) {
            if (isErr(v)) return v;
            out += toText(v);
          }
        }
        return out;
      }
      default: return "#NAME?";
    }
  }

  return ev(ast);
}
