// CSV import/export.
import { toAddr, parseAddr } from "./addr.mjs";
import { createSheet, setCell, getCell, cellAddrs } from "./sheet.mjs";

const text = (v) => (v === null || v === undefined ? "" : typeof v === "boolean" ? (v ? "TRUE" : "FALSE") : String(v));
const quote = (s) => (/[,"\n\r]/.test(s) || s.startsWith(" ") || s.endsWith(" ") ? `"${s.replace(/"/g, '""')}"` : s);

export function toCSV(sheet, values) {
  const addrs = cellAddrs(sheet);
  if (!addrs.length) return "";
  let rows = 0, cols = 0;
  for (const a of addrs) {
    const p = parseAddr(a);
    rows = Math.max(rows, p.row + 1);
    cols = Math.max(cols, p.col + 1);
  }
  let out = "";
  for (let r = 0; r < rows; r++) {
    const fields = [];
    for (let c = 0; c < cols; c++) {
      const a = toAddr(c, r);
      fields.push(quote(values ? text(values.get(a) ?? null) : getCell(sheet, a)));
    }
    out += fields.join(",") + "\n";
  }
  return out;
}

function detectDelimiter(s) {
  const counts = { ",": 0, ";": 0, "\t": 0 };
  let inQ = false;
  for (const ch of s) {
    if (ch === '"') inQ = !inQ;
    else if (!inQ) {
      if (ch === "\n") break;
      if (ch in counts) counts[ch]++;
    }
  }
  let best = ",";
  for (const d of [";", "\t"]) if (counts[d] > counts[best]) best = d;
  return best;
}

export function fromCSV(src, options = {}) {
  const sheet = createSheet();
  const delim = options.delimiter ?? detectDelimiter(src);
  let row = 0, col = 0, i = 0;
  const put = (f) => {
    if (f !== "") setCell(sheet, toAddr(col, row), f.startsWith("=") && !options.formulas ? "'" + f : f);
  };
  while (i < src.length) {
    // parse one row
    for (;;) {
      let f = "";
      if (src[i] === '"') {
        const startLine = src.slice(0, i).split("\n").length;
        i++;
        for (;;) {
          if (i >= src.length) throw new Error(`unclosed quote at line ${startLine}`);
          if (src[i] === '"') {
            if (src[i + 1] === '"') { f += '"'; i += 2; continue; }
            i++;
            break;
          }
          f += src[i++];
        }
      }
      while (i < src.length && !src.startsWith(delim, i) && src[i] !== "\n" && !(src[i] === "\r" && src[i + 1] === "\n")) f += src[i++];
      put(f);
      if (i < src.length && src.startsWith(delim, i)) { i += delim.length; col++; continue; }
      if (src[i] === "\r") i++;
      if (src[i] === "\n") i++;
      break;
    }
    row++;
    col = 0;
  }
  return sheet;
}
