// Recalculation: cell values, dependency order and dependents.
import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr, compareAddr } from "./addr.mjs";

export function valueOf(raw) {
  if (raw == null || raw === "") return null;
  const t = raw.trim();
  if (t !== "" && Number.isFinite(Number(t))) return Number(t);
  const u = t.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

const normAddr = (a) => { const p = parseAddr(a); return toAddr(p.col, p.row); };

function expandRef(ref) {
  const [a, b] = String(ref).split(":");
  if (b === undefined) return [normAddr(a)];
  const p = parseAddr(a), q = parseAddr(b);
  const out = [];
  for (let r = Math.min(p.row, q.row); r <= Math.max(p.row, q.row); r++)
    for (let c = Math.min(p.col, q.col); c <= Math.max(p.col, q.col); c++) out.push(toAddr(c, r));
  return out;
}

// Parses every formula; returns { asts, deps } where deps maps formula addr -> addrs it reads (formula cells only).
function buildGraph(sheet) {
  const asts = new Map(), deps = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (!raw.startsWith("=")) continue;
    let ast = null;
    try { ast = parseFormula(raw.slice(1)); } catch { ast = null; }
    asts.set(addr, ast);
  }
  for (const [addr, ast] of asts) {
    const set = new Set();
    if (ast) for (const ref of refsOf(ast)) {
      let list;
      try { list = expandRef(ref); } catch { continue; }
      for (const d of list) if (asts.has(d)) set.add(d);
    }
    deps.set(addr, [...set]);
  }
  return { asts, deps };
}

// Iterative Tarjan: SCCs come out dependencies-first.
function sccs(deps) {
  const index = new Map(), low = new Map(), on = new Set(), stack = [], out = [];
  let n = 0;
  for (const root of deps.keys()) {
    if (index.has(root)) continue;
    const work = [[root, 0]];
    index.set(root, n); low.set(root, n++); stack.push(root); on.add(root);
    while (work.length) {
      const top = work[work.length - 1];
      const [v, i] = top;
      const ds = deps.get(v);
      if (i < ds.length) {
        top[1]++;
        const w = ds[i];
        if (!index.has(w)) {
          index.set(w, n); low.set(w, n++); stack.push(w); on.add(w);
          work.push([w, 0]);
        } else if (on.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) { const p = work[work.length - 1][0]; low.set(p, Math.min(low.get(p), low.get(v))); }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); on.delete(w); comp.push(w); } while (w !== v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const isCycle = (comp, deps) => comp.length > 1 || deps.get(comp[0]).includes(comp[0]);

export function computeAll(sheet) {
  const { asts, deps } = buildGraph(sheet);
  const values = new Map();
  const lookup = (ref) => {
    if (String(ref).includes(":")) return expandRef(ref).map((a) => values.get(a) ?? null);
    return values.get(normAddr(ref)) ?? null;
  };
  for (const [addr, raw] of sheet.cells) if (!asts.has(addr)) values.set(addr, valueOf(raw));
  for (const comp of sccs(deps)) {
    if (isCycle(comp, deps)) { for (const a of comp) values.set(a, "#CYCLE!"); continue; }
    const a = comp[0], ast = asts.get(a);
    if (!ast) { values.set(a, "#ERROR!"); continue; }
    let v;
    try { v = evaluate(ast, lookup); } catch { v = "#ERROR!"; }
    values.set(a, v);
  }
  return values;
}

export function dependents(sheet, addr) {
  const start = normAddr(addr);
  const { deps } = buildGraph(sheet);
  const cyc = new Set();
  for (const comp of sccs(deps)) if (isCycle(comp, deps)) for (const a of comp) cyc.add(a);
  const rev = new Map();
  for (const [a, ds] of deps) for (const d of ds) {
    if (!rev.has(d)) rev.set(d, []);
    rev.get(d).push(a);
  }
  const found = new Set(), q = [start];
  while (q.length) for (const a of rev.get(q.pop()) ?? []) {
    if (found.has(a)) continue;
    found.add(a);
    q.push(a);
  }
  found.delete(start);
  for (const a of cyc) found.delete(a);
  const pending = new Map(), ready = [];
  const users = new Map();
  for (const a of found) {
    const ds = deps.get(a).filter((d) => found.has(d));
    pending.set(a, ds.length);
    for (const d of ds) { if (!users.has(d)) users.set(d, []); users.get(d).push(a); }
  }
  const push = (a) => {
    let lo = 0, hi = ready.length;
    while (lo < hi) { const m = (lo + hi) >> 1; if (compareAddr(ready[m], a) < 0) lo = m + 1; else hi = m; }
    ready.splice(lo, 0, a);
  };
  for (const [a, n] of pending) if (n === 0) push(a);
  const order = [];
  while (ready.length) {
    const a = ready.shift();
    order.push(a);
    for (const u of users.get(a) ?? []) if (--pending.set(u, pending.get(u) - 1).get(u) === 0) push(u);
  }
  return order;
}
