// Table tools: sorting a range and pivoting computed values.
import { valueOf } from "./recalc.mjs";
import { parseAddr, toAddr, colIndex } from "./addr.mjs";

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function cmpValues(a, b) {
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 0) return a - b;
  if (ra === 1) { const x = a.toLowerCase(), y = b.toLowerCase(); return x < y ? -1 : x > y ? 1 : 0; }
  return Number(a) - Number(b);
}

const parseRange = (range) => {
  const [a, b] = range.split(":");
  const p = parseAddr(a), q = parseAddr(b ?? a);
  return { c1: Math.min(p.col, q.col), c2: Math.max(p.col, q.col), r1: Math.min(p.row, q.row), r2: Math.max(p.row, q.row) };
};

export function sortRange(sheet, range, keys, options = {}) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const start = options.header ? r1 + 1 : r1;
  const rows = [];
  for (let r = start; r <= r2; r++) {
    const raws = [];
    for (let c = c1; c <= c2; c++) raws.push(sheet.cells.get(toAddr(c, r)) ?? "");
    rows.push(raws);
  }
  const ks = (keys ?? []).map((k) => ({ i: colIndex(k.col) - c1, desc: !!k.desc }));
  for (const k of ks) if (k.i < 0 || k.i > c2 - c1) throw new Error(`sort column outside range: ${keys.find((x) => colIndex(x.col) - c1 === k.i).col}`);
  const keyed = rows.map((raws) => ({ raws, vals: ks.map((k) => valueOf(raws[k.i])) }));
  keyed.sort((x, y) => {
    for (let j = 0; j < ks.length; j++) {
      const a = x.vals[j], b = y.vals[j];
      if (a === null || b === null) { if (a === b) continue; return a === null ? 1 : -1; }
      const d = cmpValues(a, b);
      if (d) return ks[j].desc ? -d : d;
    }
    return 0;
  });
  keyed.forEach(({ raws }, n) => {
    raws.forEach((raw, i) => {
      const addr = toAddr(c1 + i, start + n);
      if (raw === "") sheet.cells.delete(addr); else sheet.cells.set(addr, raw);
    });
  });
}

export function pivot(values, range, { rows, value, agg }) {
  const { c1, c2, r1, r2 } = parseRange(range);
  const names = [];
  for (let c = c1; c <= c2; c++) names.push(String(values.get(toAddr(c, r1)) ?? ""));
  const find = (name) => {
    const i = names.indexOf(name);
    if (i < 0) throw new Error(`no such column: ${name}`);
    return c1 + i;
  };
  const kc = find(rows), vc = find(value);
  const groups = new Map();
  for (let r = r1 + 1; r <= r2; r++) {
    let k = values.get(toAddr(kc, r)) ?? null;
    if (k === null) k = BLANK;
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(values.get(toAddr(vc, r)) ?? null);
  }
  const keys = [...groups.keys()].filter((k) => k !== BLANK);
  keys.sort((a, b) => cmpValues(a, b) || (typeof a === "string" ? (a < b ? -1 : a > b ? 1 : 0) : 0));
  if (groups.has(BLANK)) keys.push(BLANK);
  return keys.map((k) => ({ key: k === BLANK ? "(blank)" : k, value: aggregate(groups.get(k), agg) }));
}

const BLANK = Symbol("blank");

function aggregate(vals, agg) {
  if (agg === "count") return vals.filter((v) => v !== null).length;
  const nums = vals.filter((v) => typeof v === "number");
  if (agg === "sum") return nums.reduce((s, v) => s + v, 0);
  if (!nums.length) return null;
  if (agg === "avg") return nums.reduce((s, v) => s + v, 0) / nums.length;
  if (agg === "min") return nums.reduce((m, v) => Math.min(m, v));
  if (agg === "max") return nums.reduce((m, v) => Math.max(m, v));
  throw new Error(`unknown aggregate: ${agg}`);
}
