// Subset of spreadsheet number formats.

// Plain decimal digits of a non-negative finite number as JavaScript prints it: { int, frac } strings.
function plain(x) {
  const s = String(x);
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]\d+))?$/.exec(s);
  let int = m[1], frac = m[2] ?? "";
  const e = Number(m[3] ?? 0);
  if (e > 0) { frac = frac.padEnd(e, "0"); int += frac.slice(0, e); frac = frac.slice(e); }
  else if (e < 0) { int = int.padStart(-e + 1, "0"); frac = int.slice(e) + frac; int = int.slice(0, e); }
  return { int: int.replace(/^0+(?=\d)/, ""), frac };
}

const shift2 = ({ int, frac }) => {
  frac = frac.padEnd(2, "0");
  return { int: (int + frac.slice(0, 2)).replace(/^0+(?=\d)/, ""), frac: frac.slice(2) };
};

// Rounds half away from zero to nd decimals; returns { int, frac } with frac exactly nd long.
function round({ int, frac }, nd) {
  const up = frac.length > nd && frac[nd] >= "5";
  frac = frac.slice(0, nd).padEnd(nd, "0");
  if (!up) return { int, frac };
  const digits = (int + frac).split("");
  let i = digits.length - 1;
  for (; i >= 0; i--) {
    if (digits[i] === "9") digits[i] = "0";
    else { digits[i] = String(Number(digits[i]) + 1); break; }
  }
  let all = digits.join("");
  if (i < 0) all = "1" + all;
  return { int: all.slice(0, all.length - nd), frac: all.slice(all.length - nd) };
}

function splitSections(pattern) {
  const out = [""];
  let q = false;
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (c === '"') q = !q;
    if (c === "\\" && !q) { out[out.length - 1] += c + (pattern[++i] ?? ""); continue; }
    if (c === ";" && !q) out.push("");
    else out[out.length - 1] += c;
  }
  return out;
}

function tokenize(sec) {
  const toks = [];
  let seenDot = false;
  for (let i = 0; i < sec.length; i++) {
    const c = sec[i];
    if (c === '"') {
      const j = sec.indexOf('"', i + 1);
      const end = j < 0 ? sec.length : j;
      toks.push({ t: "lit", s: sec.slice(i + 1, end) });
      i = end;
    } else if (c === "\\") { toks.push({ t: "lit", s: sec[++i] ?? "" }); }
    else if ((c === "E" || c === "e") && (sec[i + 1] === "+" || sec[i + 1] === "-")) {
      let j = i + 2, zeros = 0;
      while (sec[j] === "0") { j++; zeros++; }
      toks.push({ t: "exp", plus: sec[i + 1] === "+", zeros });
      i = j - 1;
    } else if (c === "0" || c === "#") toks.push({ t: "d", c, frac: seenDot });
    else if (c === ".") { seenDot = true; toks.push({ t: "dot" }); }
    else if (c === ",") toks.push({ t: "comma" });
    else if (c === "%") toks.push({ t: "lit", s: "%", pct: true });
    else toks.push({ t: "lit", s: c });
  }
  return toks;
}

export function formatNumber(value, pattern) {
  if (value === null || value === undefined) return "";
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
  if (typeof value !== "number") return String(value);
  if (pattern === "General" || !Number.isFinite(value)) return String(value);

  const secs = splitSections(pattern);
  const neg = value < 0;
  let sec, sign = "";
  if (secs.length === 1) { sec = secs[0]; if (neg) sign = "-"; }
  else if (secs.length === 2) sec = neg ? secs[1] : secs[0];
  else sec = neg ? secs[1] : value === 0 ? secs[2] : secs[0];

  const toks = tokenize(sec);
  let num = plain(Math.abs(value));
  if (toks.some((t) => t.pct)) num = shift2(num);

  const fracPh = toks.filter((t) => t.t === "d" && t.frac);
  const intPh = toks.filter((t) => t.t === "d" && !t.frac);
  const nd = fracPh.length;
  const expTok = toks.find((t) => t.t === "exp");
  let exp = 0, body = {};

  let r;
  if (expTok) {
    const all = num.int.replace(/^0+/, "") + num.frac;
    if (/[1-9]/.test(all)) {
      const lead = num.int.replace(/^0+/, "").length > 0 ? num.int.length : -(num.frac.length - num.frac.replace(/^0+/, "").length) - 1 + 1;
      exp = num.int !== "0" && num.int !== "" ? num.int.length - 1 : -(num.frac.length - num.frac.replace(/^0+/, "").length + 1);
      const sig = (num.int === "0" ? "" : num.int) + num.frac;
      const digits = sig.replace(/^0+/, "");
      r = round({ int: digits[0], frac: digits.slice(1) }, nd);
      if (r.int.length > 1) { exp++; r = round({ int: "1", frac: "0".repeat(nd) }, nd); }
      void lead;
    } else r = { int: "0", frac: "0".repeat(nd) };
  } else r = round(num, nd);

  let int = r.int.replace(/^0+/, "");
  let frac = r.frac;
  const zeroResult = !/[1-9]/.test(int + frac);
  const minInt = intPh.filter((t) => t.c === "0").length;
  int = int.padStart(minInt, "0");
  if (expTok && int === "") int = "0";
  // drop trailing zeros at '#' decimal places
  let keep = frac.length;
  while (keep > 0 && fracPh[keep - 1].c === "#" && frac[keep - 1] === "0") keep--;
  frac = frac.slice(0, keep);

  // grouping: a comma between integer digit placeholders
  const firstD = toks.findIndex((t) => t.t === "d");
  const lastInt = toks.map((t) => t.t === "d" && !t.frac).lastIndexOf(true);
  const group = toks.some((t, i) => t.t === "comma" && i > firstD && i < lastInt);
  if (group) int = int.replace(/\B(?=(\d{3})+$)/g, ",");

  if (secs.length === 1 && zeroResult) sign = "";
  let out = sign, intDone = false, fracDone = false;
  for (const t of toks) {
    if (t.t === "lit") out += t.s;
    else if (t.t === "dot") out += ".";
    else if (t.t === "d") {
      if (!t.frac && !intDone) { out += int; intDone = true; }
      else if (t.frac && !fracDone) { out += frac; fracDone = true; }
    } else if (t.t === "exp") {
      const es = String(Math.abs(exp)).padStart(t.zeros, "0");
      out += "E" + (exp < 0 ? "-" : t.plus ? "+" : "") + es;
    }
  }
  void body;
  return out;
}
