// Inserting and deleting rows and columns, rewriting formula references to follow the cells.
import { parseAddr, toAddr, colIndex, colName } from "./addr.mjs";

const REF = /(?<![A-Za-z0-9_.])(\$?[A-Za-z]+\$?\d+)(?::(\$?[A-Za-z]+\$?\d+))?(?![A-Za-z0-9_.(])/g;

// op: { axis: "row" | "col", at (0-based), count, del }
function mapIndex(i, { at, count, del }) {
  if (!del) return i >= at ? i + count : i;
  if (i < at) return i;
  return i < at + count ? null : i - count;
}

function mapRange(lo, hi, { at, count, del }) {
  if (!del) return [lo >= at ? lo + count : lo, hi >= at ? hi + count : hi];
  const end = at + count;
  const f = (i, isHi) => (i < at ? i : i >= end ? i - count : isHi ? at - 1 : at);
  const nlo = f(lo, false), nhi = f(hi, true);
  return nlo > nhi ? null : [nlo, nhi];
}

const fmt = (a, col, row) => `${a.colAbs ? "$" : ""}${colName(col)}${a.rowAbs ? "$" : ""}${row + 1}`;

function rewriteRef(first, second, op) {
  const a = parseAddr(first);
  const isRow = op.axis === "row";
  if (!second) {
    const n = mapIndex(isRow ? a.row : a.col, op);
    if (n === null) return "#REF!";
    return isRow ? fmt(a, a.col, n) : fmt(a, n, a.row);
  }
  const b = parseAddr(second);
  const r = isRow
    ? mapRange(Math.min(a.row, b.row), Math.max(a.row, b.row), op)
    : mapRange(Math.min(a.col, b.col), Math.max(a.col, b.col), op);
  if (!r) return "#REF!";
  const swap = (isRow ? a.row > b.row : a.col > b.col);
  const [p, q] = swap ? [r[1], r[0]] : r;
  return isRow
    ? `${fmt(a, a.col, p)}:${fmt(b, b.col, q)}`
    : `${fmt(a, p, a.row)}:${fmt(b, q, b.row)}`;
}

function rewriteFormula(raw, op) {
  // split out string literals so they are left alone
  return raw.replace(/"(?:[^"]|"")*"|[^"]+|"/g, (part) =>
    part[0] === '"' ? part : part.replace(REF, (_, f, s) => {
      try { return rewriteRef(f, s, op); } catch { return _; }
    }));
}

function apply(sheet, op) {
  const next = new Map();
  for (const [addr, raw] of sheet.cells) {
    const a = parseAddr(addr);
    const n = mapIndex(op.axis === "row" ? a.row : a.col, op);
    if (n === null) continue;
    const key = op.axis === "row" ? toAddr(a.col, n) : toAddr(n, a.row);
    next.set(key, raw.startsWith("=") ? rewriteFormula(raw, op) : raw);
  }
  sheet.cells.clear();
  for (const [k, v] of next) sheet.cells.set(k, v);
}

export const insertRows = (sheet, at, count = 1) => apply(sheet, { axis: "row", at: at - 1, count, del: false });
export const deleteRows = (sheet, at, count = 1) => apply(sheet, { axis: "row", at: at - 1, count, del: true });
export const insertCols = (sheet, at, count = 1) => apply(sheet, { axis: "col", at: colIndex(at), count, del: false });
export const deleteCols = (sheet, at, count = 1) => apply(sheet, { axis: "col", at: colIndex(at), count, del: true });
